#include "ControlCurveComponent.h"
juce::Point<float> ControlCurveComponent::point(int i)const{auto r=getLocalBounds().toFloat().reduced(8);float x=r.getX()+r.getWidth()*i/6.0f;float v=state.getRawParameterValue(ids[i])->load();float y=juce::jmap(v,-12.0f,12.0f,r.getBottom(),r.getY());return{x,y};}
void ControlCurveComponent::paint(juce::Graphics&g){g.fillAll(juce::Colour(0xff0b1015));auto r=getLocalBounds().toFloat().reduced(8);g.setColour(juce::Colour(0xff28323c));g.drawRect(r);juce::Path p;for(int i=0;i<7;++i){auto pt=point(i);if(i==0)p.startNewSubPath(pt);else p.lineTo(pt);}g.setColour(juce::Colour(0xff9360df));g.strokePath(p,juce::PathStrokeType(2));for(int i=0;i<7;++i){g.setColour(juce::Colour(0xffc8b0f5));g.fillEllipse(juce::Rectangle<float>(10,10).withCentre(point(i)));}}
void ControlCurveComponent::mouseDown(const juce::MouseEvent&e){float best=1e9;for(int i=0;i<7;++i){float d=e.position.getDistanceFrom(point(i));if(d<best){best=d;selected=i;}}if(best>24)selected=-1;if(selected>=0)setPoint(selected,e.position.y);}
void ControlCurveComponent::mouseDrag(const juce::MouseEvent&e){if(selected>=0)setPoint(selected,e.position.y);}
void ControlCurveComponent::setPoint(int i,float y){auto r=getLocalBounds().toFloat().reduced(8);float v=juce::jmap(juce::jlimit(r.getY(),r.getBottom(),y),r.getBottom(),r.getY(),-12.0f,12.0f);if(auto*p=state.getParameter(ids[i]))p->setValueNotifyingHost(p->convertTo0to1(v));repaint();}
